return $input.all().map((item) => ({
  json: {
    publication: item.json.body.publication,
    targets: item.json.body.targets,
  },
}));

const base = $('IG Video Wait').item.json;
const status = $json.status_code;
const attempt = (base.attempt ?? 0) + 1;
const failed = status === 'ERROR' || status === 'EXPIRED' || attempt >= 20;
const errorMessage =
  status === 'ERROR'
    ? 'Instagram no pudo procesar el video'
    : status === 'EXPIRED'
      ? 'El contenedor de Instagram expiró antes de publicarse'
      : failed
        ? 'Instagram no terminó de procesar el video a tiempo'
        : undefined;
return [{ json: { ...base, attempt, status_code: status, failed, errorMessage } }];

const STAGE = 'MEDIA_PREPARATION';
const PLATFORM = 'Facebook';

function asNumber(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (trimmed === '') return null;
    const numeric = Number(trimmed);
    return Number.isFinite(numeric) ? numeric : null;
  }
  return null;
}

function asString(value) {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return trimmed === '' ? null : trimmed;
}

function asBoolean(value) {
  if (typeof value === 'boolean') return value;
  if (value === 'true') return true;
  if (value === 'false') return false;
  return null;
}

function parseJsonString(value) {
  if (typeof value !== 'string') return undefined;
  const trimmed = value.trim();
  if (!trimmed.startsWith('{') && !trimmed.startsWith('[')) return undefined;
  try {
    return JSON.parse(trimmed);
  } catch (error) {
    return undefined;
  }
}

function isMetaError(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const keys = [
    'code',
    'error_subcode',
    'errorSubcode',
    'subcode',
    'fbtrace_id',
    'trace_id',
    'traceId',
    'is_transient',
    'isTransient',
    'error_user_msg',
  ];
  return keys.some((key) => value[key] !== undefined && value[key] !== null);
}

function collectCandidates(root) {
  const candidates = [];
  const seen = new Set();

  function visit(value, depth) {
    if (value === null || value === undefined || depth > 10) return;
    if (typeof value === 'string') {
      const parsed = parseJsonString(value);
      if (parsed !== undefined) visit(parsed, depth + 1);
      return;
    }
    if (typeof value !== 'object') return;
    if (seen.has(value)) return;
    seen.add(value);
    if (Array.isArray(value)) {
      for (const child of value) visit(child, depth + 1);
      return;
    }
    if (isMetaError(value)) candidates.push(value);
    for (const child of Object.values(value)) visit(child, depth + 1);
  }

  visit(root, 0);
  return candidates;
}

function scoreCandidate(candidate) {
  let score = 0;
  if (asNumber(candidate.error_subcode ?? candidate.errorSubcode ?? candidate.subcode) !== null) score += 16;
  if (asString(candidate.fbtrace_id ?? candidate.trace_id ?? candidate.traceId) !== null) score += 8;
  if (asString(candidate.error_user_msg ?? candidate.errorUserMsg) !== null) score += 8;
  if (asString(candidate.type) !== null) score += 4;
  if (asBoolean(candidate.is_transient ?? candidate.isTransient) !== null) score += 4;
  if (asNumber(candidate.code) !== null) score += 2;
  if (asString(candidate.message) !== null) score += 1;
  return score;
}

function pickMeta(candidates) {
  let best = null;
  let bestScore = -1;
  for (const candidate of candidates) {
    const score = scoreCandidate(candidate);
    if (score > bestScore) {
      best = candidate;
      bestScore = score;
    }
  }
  return best;
}

function firstDefined(values, mapper) {
  for (const value of values) {
    const result = mapper(value);
    if (result !== null && result !== undefined) return result;
  }
  return null;
}

function safeHttpStatus(value) {
  const status = asNumber(value);
  return status !== null && status >= 100 && status <= 599 ? status : null;
}

function normalize(input) {
  const sources = [];
  if (input && typeof input === 'object') {
    if (input.details) sources.push(input.details);
    if (input.error) sources.push(input.error);
    if (input.response) sources.push(input.response);
  }

  const candidates = [];
  for (const source of sources) {
    for (const candidate of collectCandidates(source)) candidates.push(candidate);
  }

  const meta = pickMeta(candidates) ?? {};

  const httpStatus = firstDefined(
    [
      input?.details?.httpCode,
      input?.error?.httpCode,
      input?.error?.statusCode,
      input?.error?.response?.status,
      input?.response?.status,
      input?.response?.statusCode,
      input?.httpCode,
      input?.statusCode,
      meta.httpStatus,
    ],
    safeHttpStatus,
  );

  const code = firstDefined([meta.code, input?.error?.code], asNumber);
  const subcode = firstDefined(
    [meta.error_subcode, meta.errorSubcode, meta.subcode, input?.error?.error_subcode, input?.error?.subcode],
    asNumber,
  );
  const providerMessage = firstDefined(
    [
      meta.message,
      meta.error_user_msg,
      meta.errorUserMsg,
      input?.details?.message,
      input?.error?.message,
      input?.error,
      input?.message,
    ],
    asString,
  );
  const fallbackMessage = firstDefined([input?.errorMessage], asString);
  const message = providerMessage ?? fallbackMessage ?? 'Error publicando en ' + PLATFORM;
  const errorMessage = (httpStatus !== null ? httpStatus + ' - ' : '') + message;

  const error = {};
  if (code !== null) error.code = code;
  if (subcode !== null) error.subcode = subcode;
  if (message !== null) error.message = message.slice(0, 5000);
  const type = firstDefined([meta.type, input?.error?.type], asString);
  if (type !== null) error.type = type.slice(0, 200);
  const isTransient = firstDefined([meta.is_transient, meta.isTransient, input?.error?.isTransient], asBoolean);
  if (isTransient !== null) error.isTransient = isTransient;
  if (httpStatus !== null) error.httpStatus = httpStatus;
  const traceId = firstDefined([meta.fbtrace_id, meta.trace_id, meta.traceId, input?.error?.fbtrace_id], asString);
  if (traceId !== null) error.traceId = traceId.slice(0, 200);
  const retryAfterSeconds = firstDefined(
    [meta.retry_after, meta.retryAfterSeconds, input?.error?.retryAfterSeconds],
    asNumber,
  );
  if (retryAfterSeconds !== null && retryAfterSeconds >= 0) error.retryAfterSeconds = retryAfterSeconds;

  const target = input?.targets?.target ?? input?.target ?? {};
  const targetId = firstDefined([target.id], asString);
  const dispatchAttemptId = firstDefined(
    [input?.publication?.dispatchAttemptId, input?.dispatchAttemptId],
    asString,
  );

  return {
    targetId,
    dispatchAttemptId,
    stage: STAGE,
    errorMessage: errorMessage.slice(0, 5000),
    error: Object.keys(error).length > 0 ? error : undefined,
  };
}

return $input.all().map((item, index) => ({
  json: normalize(item.json ?? {}),
  pairedItem: { item: index },
}));

